    PairNode *oldRoot = root;

    if( root->leftChild == nullptr )
        root = nullptr;
    else
        root = combineSiblings( root->leftChild );

    delete oldRoot;
}

/**
 * 实现两趟合并的内部方法.
 * firstSibling 合并后的树的根，并假设不是 nullptr.
 */
PairNode * combineSiblings( PairNode *firstSibling )
{
    if( firstSibling->nextSibling == nullptr )
        return firstSibling;

    // 配置数组
    static vector<PairNode *> treeArray( 5 );

    // 将各子树存储在一个数组中
    int numSiblings = 0;
    for( ; firstSibling != nullptr; ++numSiblings )
    {
        if( numSiblings == treeArray.size( ) )
            treeArray.resize( numSiblings * 2 );
        treeArray[ numSiblings ] = firstSibling;
        firstSibling->prev->nextSibling = nullptr;  // 断开链接
        firstSibling = firstSibling->nextSibling;
    }
    if( numSiblings == treeArray.size( ) )
        treeArray.resize( numSiblings + 1 );
        treeArray[ numSiblings ] = nullptr;

        // 从左到右，一次合并两棵子树
    int i = 0;
    for( ; i + 1 < numSiblings; i += 2 )
        compareAndLink( treeArray[ i ], treeArray[ i + 1 ] );

    int j = i - 2;

    // j 有最新 compareAndLink 的结果。
    // 如果是奇数棵树，则获取最后一棵。
    if( j == numSiblings - 3 )
        compareAndLink( treeArray[ j ], treeArray[ j + 2 ] );

    // 现在从右到左，将最后一棵树与
    // 倒数第二棵合并。结果成为新的最终的树。
    for( ; j >= 2; j -= 2 )
        compareAndLink( treeArray[ j - 2 ], treeArray[ j ] );
    return treeArray[ 0 ];
}

/*
 * 由后缀数组创建 LCP 数组
 * s 为输入数组, 数组元素从 0..N-1 填充, 其位置 N 也是可用的
 * sa 是一个已经算出的后缀数组 0..N-1
 * LCP 是最后得到的 LCP 数组 0..N-1
 */
void makeLCPArray( vector<int> & s, const vector<int> & sa, vector<int> & LCP )
{
    int N = sa.size( );
    vector<int> rank( N );

    s[ N ] = -1;
    for( int i = 0; i < N; ++i )
        rank[ sa[ i ] ] = i;

    int h = 0;
    for( int i = 0; i < N; ++i )
        if( rank[ i ] > 0 )
        {
            int j = sa[ rank[ i ] - 1 ];


            while( s[ i + h ] == s[ j + h ] )
                ++h;

            LCP[ rank[ i ] ] = h;
            if( h > 0 )
                --h;
        }
}

